export const workspaces = pgTable("workspaces", {
  id: uuid("id").defaultRandom().primaryKey(),
  ownerId: uuid("owner_id").notNull().unique().references(() => authUsers.id, { onDelete: "cascade" }),
  name: text("name").notNull().default("My finances"),
  displayCurrency: text("display_currency").notNull().default("EUR"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
});

export const accounts = pgTable("accounts", {
  id: uuid("id").defaultRandom().primaryKey(),
  workspaceId: uuid("workspace_id").notNull().references(() => workspaces.id),
  name: text("name").notNull(),
  type: text("type").notNull().default("checking"),
  currencyCode: text("currency_code").notNull(),
  version: integer("version").notNull().default(1),
  archivedAt: timestamp("archived_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
});

export const balanceSnapshots = pgTable("balance_snapshots", {
  id: uuid("id").defaultRandom().primaryKey(),
  check("bank_connections_provider_check", sql`${table.provider} = 'enable_banking'`),
  check("bank_connections_aspsp_name_check", sql`char_length(${table.aspspName}) between 1 and 200`),
  check("bank_connections_aspsp_country_check", sql`${table.aspspCountry} ~ '^[A-Z]{2}$'`),
  check("bank_connections_status_check", sql`${table.status} in ('pending','active','expired','revoked','error')`),
  check("bank_connections_last_error_check", sql`char_length(${table.lastError}) <= 1000`),
  check("bank_connections_check", sql`${table.status} <> 'active' or (${table.sessionIdEncrypted} is not null and ${table.validUntil} is not null)`),
]);

export const bankConnectionAccounts = pgTable("bank_connection_accounts", {
  connectionId: uuid("connection_id").notNull().references(() => bankConnections.id, { onDelete: "cascade" }),
  workspaceId: uuid("workspace_id").notNull().references(() => workspaces.id),
  providerAccountUid: text("provider_account_uid").notNull(),
  iban: text("iban"),
  currencyCode: text("currency_code").notNull(),
  accountName: text("account_name").notNull(),
  lastBookedOn: date("last_booked_on"),
}, (table) => [
  primaryKey({ columns: [table.connectionId, table.providerAccountUid] }),
  check("bank_connection_accounts_provider_account_uid_check", sql`char_length(${table.providerAccountUid}) between 1 and 200`),
  check("bank_connection_accounts_iban_check", sql`char_length(${table.iban}) <= 34`),
  check("bank_connection_accounts_currency_code_check", sql`${table.currencyCode} ~ '^[A-Z]{3}$'`),
  check("bank_connection_accounts_account_name_check", sql`char_length(${table.accountName}) between 1 and 100`),
]);

export const importControlEvents = pgTable("import_control_events", {
  id: uuid("id").defaultRandom().primaryKey(),
  workspaceId: uuid("workspace_id").notNull().references(() => workspaces.id),
  importId: uuid("import_id").notNull().references(() => imports.id),
  requestId: uuid("request_id").notNull(), action: text("action").notNull(), result: jsonb("result").notNull(),
  actorId: uuid("actor_id").notNull().references(() => authUsers.id),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, table => [unique("import_control_events_workspace_id_request_id_key").on(table.workspaceId, table.requestId),
  check("import_control_events_action_check", sql`${table.action} in ('cancel','resume')`),
  check("import_control_events_result_check", sql`jsonb_typeof(${table.result}) = 'object'`)]);

export const importStaging = pgTable("import_staging", {
  importId: uuid("import_id").primaryKey().references(() => imports.id, { onDelete: "cascade" }),
  workspaceId: uuid("workspace_id").notNull().references(() => workspaces.id),
  stageVersion: integer("stage_version").notNull(),
  fileHash: text("file_hash").notNull(),
  mapping: jsonb("mapping").notNull(),
  routeAccounts: jsonb("route_accounts").notNull(),
  rows: jsonb("rows").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, table => [
  check("import_staging_stage_version_check", sql`${table.stageVersion} = 1`),
  check("import_staging_rows_check", sql`jsonb_typeof(${table.rows}) = 'array' and jsonb_array_length(${table.rows}) <= 10000 and octet_length(${table.rows}::text) <= 64000000`),
]);

export const sourceTransactions = pgTable("source_transactions", {
  id: uuid("id").defaultRandom().primaryKey(),
  workspaceId: uuid("workspace_id").notNull().references(() => workspaces.id),
  importId: uuid("import_id").notNull().references(() => imports.id),
  rowNumber: integer("row_number").notNull(),
  originalRow: jsonb("original_row").notNull(),
  feeEvidence: jsonb("fee_evidence"),
  normalizedRow: jsonb("normalized_row"),
  externalId: text("external_id"),
  reviewReasons: text("review_reasons").array().notNull().default(sql`'{}'::text[]`),
  status: text("status").notNull().default("new"),
}, (table) => [
  index("source_transactions_import_external_idx").using("hash", table.externalId),
  check("source_transactions_normalized_row_check", sql`${table.normalizedRow} is null or jsonb_typeof(${table.normalizedRow}) = 'object'`),
  unique("source_transactions_import_row_unique").on(table.importId, table.rowNumber),
  check("source_transactions_fee_evidence_check", sql`${table.feeEvidence} is null or (jsonb_typeof(${table.feeEvidence}) = 'object' and ${table.feeEvidence} ? 'treatment' and ${table.feeEvidence}->>'treatment' is not null and ${table.feeEvidence}->>'treatment' in ('included','additional','unknown'))`),
  check("source_transactions_review_reasons_check", sql`${table.reviewReasons} <@ array['source_transfer','source_exchange','source_type','refund_sign','fee_semantics','excluded_by_review']::text[]`),
]);

export const categories = pgTable("categories", {
  id: uuid("id").defaultRandom().primaryKey(),
  workspaceId: uuid("workspace_id").notNull().references(() => workspaces.id),
  name: text("name").notNull(),
}, (table) => [unique("categories_workspace_name_unique").on(table.workspaceId, table.name)]);

export const merchants = pgTable("merchants", {
  id: uuid("id").defaultRandom().primaryKey(),
  workspaceId: uuid("workspace_id").notNull().references(() => workspaces.id),
  name: text("name").notNull(),
  normalizedName: text("normalized_name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
